"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[20286],{58242:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"HoldAnimConfig","desc":"Hold and action animations per held Tool, keyed by the hold name (`holdName`).\\nGuns use the gun rig (`GunRig`: Hold / Fire / Reload clips); the throwables and\\nthe Grabhook are held in the hand (`Tools`, `Fire`). Played on the local character\\nby `ToolHoldAnimController` / `WeaponAnims` and on armed pirates by `EnemyGear`. A\\nTool with no entry keeps the default Roblox tool pose (pirates: the static arm raise).","source":{"line":11,"path":"src/ReplicatedStorage/SharedModules/Configs/HoldAnimConfig.luau"}}')}}]);